/* Diva Desk - keyboard, focus and workflow layer (DEC-85 to DEC-90).
 *
 * Loaded through `app_include_js` by the `diva_desk` app. Everything that
 * touches permissions, money, stock or payments lives on the server in
 * `diva_guard.desk_api`; this file only moves the cursor and opens dialogs.
 *
 * Item             : the Item list "Add" opens the Diva item dialog (item +
 *                    opening stock reconciliation); a blank barcode is
 *                    generated by the server.
 * Purchase Receipt : supplier -> accepted warehouse -> item row (inline, no
 *                    row editor), Add New Item opens the standard quick entry,
 *                    Print after submit.
 * Sales Invoice    : customer -> item row, Pay (full or partial, Cash).
 * Shortcuts        : F1 help, F2 party, F3 item, F8 pay, F9 print,
 *                    Ctrl+S save, Ctrl+Enter submit.
 * Search           : the Desk search bar (Ctrl+K) is extended by the
 *                    `awesomebar_search` hook in diva_guard.
 */
(function () {
	"use strict";

	const DEFAULT_PAYMENT_MODE = "Cash";
	const INVOICE_PRINT_FORMAT = "Diva Sales Invoice A4";
	const PURCHASE_INVOICE_PRINT_FORMAT = "Diva Purchase Invoice A4";
	const PAYMENT_RECEIPT_PRINT_FORMAT = "Diva Payment Receipt";
	const RECEIPT_PRINT_FORMAT = "Diva Purchase Receipt A4";

	// ------------------------------------------------------------------
	// Helpers
	// ------------------------------------------------------------------
	function money(value) {
		return format_currency(flt(value), frappe.defaults.get_default("currency") || "EGP");
	}

	function is_new(frm) {
		return Boolean(frm && frm.doc && frm.doc.__islocal);
	}

	function is_draft(frm) {
		return Boolean(frm && frm.doc && frm.doc.docstatus === 0);
	}

	function is_submitted(frm) {
		return Boolean(frm && frm.doc && frm.doc.docstatus === 1);
	}

	function focus_field(frm, fieldname) {
		const field = frm && frm.fields_dict && frm.fields_dict[fieldname];
		if (!field) return;
		setTimeout(() => {
			if (typeof field.set_focus === "function") {
				field.set_focus();
			} else if (field.$input && field.$input.length) {
				field.$input.trigger("focus");
			}
			const input = field.$input && field.$input.get(0);
			if (input && input.select) input.select();
		}, 150);
	}

	// Focus the item-code cell inline. The full row editor opens only from the
	// pin/expand icon, never from Tab (DEC-90). Clicking the grid cell turns it
	// into an inline input; Tab then moves to the next cell.
	function focus_item_row(frm) {
		const items = frm && frm.fields_dict && frm.fields_dict.items;
		const grid = items && items.grid;
		if (!grid) return;
		if (!(grid.grid_rows || []).length) {
			// show=false: add the row without opening the full row editor.
			grid.add_new_row(null, null, false, null, false);
		}
		setTimeout(() => {
			const $cell = grid.wrapper.find(".grid-row").last().find('[data-fieldname="item_code"]').first();
			if (!$cell.length) return;
			const cell = $cell.get(0);
			if (cell.scrollIntoView) cell.scrollIntoView({ block: "nearest" });
			cell.click();
			const input = $cell.find("input").get(0);
			if (input) {
				input.focus();
				if (input.select) input.select();
			}
		}, 300);
	}

	function open_print(doctype, name, printFormat, trigger) {
		const params = new URLSearchParams({
			doctype: doctype,
			name: name,
			format: printFormat,
			no_letterhead: "1",
		});
		if (trigger) params.set("trigger_print", "1");
		window.open("/printview?" + params.toString(), "_blank");
	}

	function open_whatsapp(frm) {
		frappe
			.xcall("diva_guard.share.invoice_share", {
				doctype: frm.doctype,
				name: frm.doc.name,
				language: frappe.boot && frappe.boot.lang === "en" ? "en" : "ar",
			})
			.then((result) => window.open(result.wa_link, "_blank"))
			.catch((error) => {
				frappe.msgprint({
					title: __("Open in WhatsApp failed"),
					message: (error && (error.message || error._server_messages)) || String(error),
					indicator: "red",
				});
			});
	}

	function add_share_buttons(frm, printFormat) {
		frm.add_custom_button(__("Open in WhatsApp"), () => open_whatsapp(frm));
		frm.add_custom_button(__("Download PDF"), () =>
			open_print(frm.doctype, frm.doc.name, printFormat, true)
		);
		frm.add_custom_button(__("Print"), () => open_print(frm.doctype, frm.doc.name, printFormat));
	}

	function fieldname_of(element) {
		const control = $(element).closest("[data-fieldname]");
		return control.length ? control.attr("data-fieldname") : null;
	}

	// ------------------------------------------------------------------
	// Purchase Invoice: Print button (submitted)
	// ------------------------------------------------------------------
	frappe.ui.form.on("Purchase Invoice", {
		refresh(frm) {
			if (is_submitted(frm)) {
				add_share_buttons(frm, PURCHASE_INVOICE_PRINT_FORMAT);
			}
		},
	});

	frappe.ui.form.on("Payment Entry", {
		refresh(frm) {
			if (is_submitted(frm)) {
				add_share_buttons(frm, PAYMENT_RECEIPT_PRINT_FORMAT);
			}
		},
	});

	// ------------------------------------------------------------------
	// Purchase Receipt
	// ------------------------------------------------------------------
	frappe.ui.form.on("Purchase Receipt", {
		refresh(frm) {
			if (is_draft(frm)) {
				focus_field(frm, "supplier");
				frm.add_custom_button(__("Add New Item"), () => frappe.ui.form.make_quick_entry("Item"));
				// Saving a Purchase Receipt must never submit it by accident: the
				// primary action stays Save, and Submit is an explicit button.
				frm.page.set_primary_action(__("Save"), () => frm.save());
				frm.add_custom_button(__("Submit"), () => frm.savesubmit());
			}
			if (is_submitted(frm)) {
				frm.add_custom_button(__("Print"), () =>
					open_print("Purchase Receipt", frm.doc.name, RECEIPT_PRINT_FORMAT)
				);
			}
		},
	});

	// ------------------------------------------------------------------
	// Sales Invoice: Pay (full or partial). Print stays in the standard menu.
	// ------------------------------------------------------------------
	function pay_invoice_dialog(frm) {
		if (!is_submitted(frm) || flt(frm.doc.outstanding_amount) <= 0) {
			frappe.show_alert({
				message: __("This invoice has nothing left to pay."),
				indicator: "orange",
			});
			return;
		}
		const outstanding = flt(frm.doc.outstanding_amount);
		const dialog = new frappe.ui.Dialog({
			title: __("Pay Invoice {0}", [frm.doc.name]),
			fields: [
				{
					fieldname: "pay_full",
					label: __("Pay the full outstanding amount"),
					fieldtype: "Check",
					default: 1,
				},
				{
					fieldname: "amount",
					label: __("Amount to pay"),
					fieldtype: "Currency",
					reqd: 1,
					default: outstanding,
				},
				{
					fieldname: "mode_of_payment",
					label: __("Mode of Payment"),
					fieldtype: "Link",
					options: "Mode of Payment",
					reqd: 1,
					default: DEFAULT_PAYMENT_MODE,
				},
				{ fieldname: "reference_no", label: __("Reference No"), fieldtype: "Data" },
				{
					fieldname: "reference_date",
					label: __("Payment Date"),
					fieldtype: "Date",
					default: frappe.datetime.get_today(),
				},
				{
					fieldtype: "HTML",
					options: `<div class="text-muted small">${__(
						"Nothing is posted until you press Pay. The payment is then reviewed by a human, as always."
					)}</div>`,
				},
			],
			primary_action_label: __("Pay"),
			primary_action(values) {
				const amount = flt(values.amount);
				if (amount <= 0 || amount > outstanding + 0.005) {
					frappe.msgprint(__("Enter an amount between 0 and {0}", [money(outstanding)]));
					return;
				}
				dialog.hide();
				frappe.dom.freeze(__("Creating the payment..."));
				frappe
					.xcall("diva_guard.desk_api.pay_invoice", {
						invoice_name: frm.doc.name,
						amount: amount,
						mode_of_payment: values.mode_of_payment,
						reference_no: values.reference_no || "",
						reference_date: values.reference_date || frappe.datetime.get_today(),
					})
					.then((result) => {
						frappe.show_alert({
							message: __("Payment {0} submitted.", [result.payment_entry]),
							indicator: "green",
						});
						frm.reload_doc();
					})
					.catch((error) => {
						frappe.msgprint({
							title: __("Payment failed"),
							message: (error && (error.message || error._server_messages)) || String(error),
							indicator: "red",
						});
					})
					.finally(() => frappe.dom.unfreeze());
			},
		});

		const syncAmountMode = () => {
			const full = Boolean(dialog.get_value("pay_full"));
			dialog.set_value("amount", full ? outstanding : flt(dialog.get_value("amount")) || outstanding);
			dialog.set_df_property("amount", "read_only", full ? 1 : 0);
			dialog.set_df_property(
				"amount",
				"description",
				full ? __("Full outstanding amount") : __("Partial payment")
			);
		};
		dialog.fields_dict.pay_full.$input.on("change", syncAmountMode);
		dialog.show();
		syncAmountMode();
		setTimeout(() => dialog.fields_dict.pay_full.$input.trigger("focus"), 150);
	}

	frappe.ui.form.on("Sales Invoice", {
		refresh(frm) {
			if (is_draft(frm)) {
				focus_field(frm, "customer");
			}
			if (is_submitted(frm)) {
				add_share_buttons(frm, INVOICE_PRINT_FORMAT);
				if (flt(frm.doc.outstanding_amount) > 0) {
					frm.add_custom_button(__("Pay"), () => pay_invoice_dialog(frm));
				}
			}
		},
	});

	// ------------------------------------------------------------------
	// Keyboard shortcuts
	// ------------------------------------------------------------------
	function shortcut_help() {
		const rows = [
			["F1", __("Show these shortcuts")],
			["F2", __("Focus customer / supplier")],
			["F3", __("Add or focus the item row")],
			["F8", __("Pay the Sales Invoice")],
			["F9", __("Print the current document")],
			["Tab", __("Accept the first suggestion, then jump on")],
			["Ctrl+S", __("Save")],
			["Ctrl+Enter", __("Submit")],
			["Ctrl+K", __("Search items, parties and invoices")],
		];
		const html = `<table class="table table-sm">${rows
			.map(
				([key, label]) =>
					`<tr><td style="width:110px"><kbd>${key}</kbd></td><td>${label}</td></tr>`
			)
			.join("")}</table>`;
		frappe.msgprint({ title: __("Diva shortcuts"), message: html, wide: true });
	}

	// Tab accepts the first open Link suggestion instead of leaving the field.
	function select_first_link_suggestion(input) {
		if (!input.value || !input.value.trim()) return false;
		const list = input.closest ? input.closest(".awesomplete") : null;
		const ul = list && list.querySelector("ul[role='listbox']");
		if (!ul || ul.hasAttribute("hidden") || !ul.children.length) return false;
		const fire = (key, keyCode) =>
			input.dispatchEvent(
				new KeyboardEvent("keydown", {
					key: key,
					keyCode: keyCode,
					which: keyCode,
					bubbles: true,
					cancelable: true,
				})
			);
		fire("ArrowDown", 40);
		fire("Enter", 13);
		return true;
	}

	function tab_target(frm, fieldname) {
		if (!frm) return null;
		if (frm.doctype === "Purchase Receipt") {
			if (fieldname === "supplier") return () => focus_field(frm, "set_warehouse");
			if (fieldname === "set_warehouse") return () => focus_item_row(frm);
		}
		if (frm.doctype === "Sales Invoice" && fieldname === "customer") {
			return () => focus_item_row(frm);
		}
		return null;
	}

	function active_form() {
		return window.cur_frm && window.cur_frm.doc ? window.cur_frm : null;
	}

	// app_include_js loads this on every Desk page; only the two owner documents
	// get the Tab order and the save/submit keys.
	function is_desk_form(frm) {
		return Boolean(frm && (frm.doctype === "Purchase Receipt" || frm.doctype === "Sales Invoice"));
	}

	function dialog_is_open() {
		return $(".modal:visible").length > 0;
	}

	document.addEventListener(
		"keydown",
		(event) => {
			const input = event.target;
			if (event.key === "Tab" && input && input.tagName === "INPUT") {
				const frm = active_form();
				const desk_form = is_desk_form(frm);
				if (!desk_form || dialog_is_open()) return;
				const fieldname = fieldname_of(input);
				const jump = tab_target(frm, fieldname);
				// Supplier -> warehouse -> items and Customer -> items always jump.
				// Any other Link field accepts the first suggestion when it has text.
				if (jump) {
					event.preventDefault();
					jump();
					return;
				}
				if (select_first_link_suggestion(input)) {
					event.preventDefault();
				}
			}

			if (event.key === "F1") {
				event.preventDefault();
				shortcut_help();
				return;
			}

			const frm = active_form();
			if (!frm || dialog_is_open() || !is_desk_form(frm)) return;
			const isSalesInvoice = frm.doctype === "Sales Invoice";
			const isPurchaseReceipt = frm.doctype === "Purchase Receipt";

			if (event.key === "F2") {
				event.preventDefault();
				if (isPurchaseReceipt) focus_field(frm, "supplier");
				else if (isSalesInvoice) focus_field(frm, "customer");
			} else if (event.key === "F3") {
				event.preventDefault();
				focus_item_row(frm);
			} else if (event.key === "F8" && isSalesInvoice) {
				event.preventDefault();
				pay_invoice_dialog(frm);
			} else if (event.key === "F9" && is_submitted(frm)) {
				event.preventDefault();
				if (isSalesInvoice) open_print("Sales Invoice", frm.doc.name, INVOICE_PRINT_FORMAT);
				else if (isPurchaseReceipt) {
					open_print("Purchase Receipt", frm.doc.name, RECEIPT_PRINT_FORMAT);
				}
			} else if (event.key.toLowerCase() === "s" && (event.ctrlKey || event.metaKey)) {
				if (!is_draft(frm)) return;
				event.preventDefault();
				frm.save();
			} else if (event.key === "Enter" && (event.ctrlKey || event.metaKey)) {
				if (!is_draft(frm)) return;
				event.preventDefault();
				frm.save("Submit");
			}
		},
		true
	);

	// ------------------------------------------------------------------
	// Item list: Left stock column and the primary barcode (DEC-96)
	// ------------------------------------------------------------------
	function enrich_item_list(listview) {
		if (!listview || listview.doctype !== "Item" || listview.view !== "List") return;
		if (listview._diva_stock_loading) return;
		const names = (listview.data || []).map((row) => row.name);
		if (!names.length) return;
		listview._diva_stock_loading = true;
		frappe
			.xcall("diva_guard.item_list.left_stock", { items: names })
			.then((totals) => {
				(listview.data || []).forEach((row) => {
					row.left_stock = (totals && totals[row.name]) || 0;
				});
				listview.render_list();
			})
			.finally(() => {
				listview._diva_stock_loading = false;
			});
	}

	function patch_item_list(listview) {
		if (
			!listview ||
			listview.doctype !== "Item" ||
			listview.view !== "List" ||
			listview._diva_patched
		) {
			return;
		}
		listview._diva_patched = true;
		listview.columns = (listview.columns || []).filter(
			(column) => !(column.df && column.df.fieldname === "opening_stock")
		);
		if (!(listview.columns || []).some((column) => column.df && column.df.fieldname === "left_stock")) {
			listview.columns.push({
				type: "Field",
				df: { fieldname: "left_stock", label: __("Left stock"), fieldtype: "Float" },
			});
		}
		if (listview.header) listview.render_header(true);
		const original_refresh = listview.refresh.bind(listview);
		listview.refresh = function (...args) {
			const result = original_refresh(...args);
			if (result && typeof result.then === "function") {
				result.then(() => enrich_item_list(listview));
			} else {
				setTimeout(() => enrich_item_list(listview), 800);
			}
			return result;
		};
		enrich_item_list(listview);
	}

	setInterval(() => {
		if (window.cur_list) patch_item_list(window.cur_list);
	}, 1000);

})();
